// Prepare AI Prompt Inputs
const lead = $('Multi-Client Router & Lead Extractor').first().json.lead;
const clientConfig = $('Multi-Client Router & Lead Extractor').first().json.clientConfig;

const systemPrompt = `You are an elite AI Sales Automation & Qualification Agent representing ${clientConfig.clientName}.
Your tone of voice is: ${clientConfig.brandVoicePrompt}

Task:
1. Analyze lead qualification based on the available data.
2. Assign an Intent Score from 1 to 10.
3. Draft a concise, personalized outreach email (3-4 paragraphs max) that invites the lead to explore next steps.

You must return STRICT JSON format with keys:
{
  "leadScore": <number 1-10>,
  "intentCategory": "High" | "Medium" | "Low",
  "qualificationSummary": "<1 sentence rationale>",
  "emailSubject": "<compelling subject line>",
  "emailBodyHtml": "<clean HTML email body>",
  "emailBodyText": "<plain text email body>"
}`;

const userPrompt = `Lead Name: ${lead.fullName}
Email: ${lead.primaryEmail}
Phone: ${lead.primaryPhone}
Company: ${lead.companyName}
Job Title: ${lead.jobTitle}
Acquisition Source: ${lead.source}`;

return [{
  json: {
    lead,
    clientConfig,
    systemPrompt,
    userPrompt
  }
}];

// Parse AI response and merge with lead context
const rawAi = $input.item.json.choices?.[0]?.message?.content || "{}";
let aiParsed = {};
try {
  aiParsed = JSON.parse(rawAi);
} catch (e) {
  aiParsed = {
    leadScore: 7,
    intentCategory: "Medium",
    qualificationSummary: "Auto-qualified inbound contact",
    emailSubject: "Excited to connect with " + $('Format AI Qualification Prompt').first().json.lead.companyName,
    emailBodyText: "Hello " + $('Format AI Qualification Prompt').first().json.lead.firstName + ", thank you for reaching out to us!",
    emailBodyHtml: "<p>Hello " + $('Format AI Qualification Prompt').first().json.lead.firstName + ",</p><p>Thank you for reaching out to us!</p>"
  };
}

const lead = $('Format AI Qualification Prompt').first().json.lead;
const clientConfig = $('Format AI Qualification Prompt').first().json.clientConfig;

// Generate unique UUID for note
const noteId = (typeof crypto !== "undefined" && crypto.randomUUID) ? crypto.randomUUID() : "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === "x" ? r : (r & 0x3 | 0x8);
    return v.toString(16);
});

return [{
  json: {
    lead,
    clientConfig,
    aiResult: aiParsed,
    noteId
  }
}];

